import torch
import torch.nn.functional as F

def shared_plus_top2_dispatch(x: torch.Tensor, shared_fn, experts: list, router_logits: torch.Tensor) -> torch.Tensor:
    probs = F.softmax(router_logits, dim=-1)
    w, idx = torch.topk(probs, k=2, dim=-1)
    w = w / (w.sum(dim=-1, keepdim=True) + 1e-8)
    routed = torch.zeros_like(x)
    for k in range(2):
        for e_id, exp in enumerate(experts):
            mask = (idx[..., k] == e_id).unsqueeze(-1)
            if mask.any():
                routed = routed + mask * w[..., k].unsqueeze(-1) * exp(x)
    return 0.35 * shared_fn(x) + 0.65 * routed
